// ─── logos.cpp ────────────────────────────────────────────────────────────────
#include "logos.h"
#include "skin.h"                 // decodeImageData
#include "embedded_images.h"      // generated by CMake from assets/logo/*.png
#include <SDL2/SDL.h>
#include <SDL2/SDL_opengl.h>

namespace {

struct Source { const unsigned char* data; size_t size; };

const Source SOURCES[Logos::COUNT] = {
    { EMBED_logo01, sizeof(EMBED_logo01) },   // Wave
    { EMBED_logo02, sizeof(EMBED_logo02) },   // Badge
    { EMBED_logo00, sizeof(EMBED_logo00) },   // Wordmark
};

Logos::Texture g_tex[Logos::COUNT];
bool           g_tried[Logos::COUNT] = {};

} // namespace

const Logos::Texture& Logos::get(Id id) {
    Texture& t = g_tex[id];
    if (t.tex || g_tried[id]) return t;
    g_tried[id] = true;

    SkinImage img;
    if (!decodeImageData(SOURCES[id].data, SOURCES[id].size, img)) return t;
    glGenTextures(1, &t.tex);
    glBindTexture(GL_TEXTURE_2D, t.tex);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_LINEAR);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_LINEAR);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_S, GL_CLAMP_TO_EDGE);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_T, GL_CLAMP_TO_EDGE);
    glPixelStorei(GL_UNPACK_ALIGNMENT, 4);
    glTexImage2D(GL_TEXTURE_2D, 0, GL_RGBA, img.w, img.h, 0, GL_RGBA, GL_UNSIGNED_BYTE, img.rgba.data());
    glBindTexture(GL_TEXTURE_2D, 0);
    t.w = img.w;
    t.h = img.h;
    return t;
}

void Logos::setWindowIcon(SDL_Window* win) {
#ifndef _WIN32
    SkinImage img;
    if (!win || !decodeImageData(SOURCES[Badge].data, SOURCES[Badge].size, img)) return;
    SDL_Surface* s = SDL_CreateRGBSurfaceWithFormatFrom(img.rgba.data(), img.w, img.h, 32, img.w * 4,
                                                        SDL_PIXELFORMAT_RGBA32);
    if (s) { SDL_SetWindowIcon(win, s); SDL_FreeSurface(s); }
#else
    (void)win;
#endif
}

void Logos::release() {
    for (int i = 0; i < COUNT; ++i) {
        if (g_tex[i].tex) glDeleteTextures(1, &g_tex[i].tex);
        g_tex[i] = {};
        g_tried[i] = false;
    }
}
